contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public test function: take the amount to send as input
    function run(uint amount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (amount)); require(amount <= 1000000000000000000000000000000);
        // ensure this test contract has enough balance to send amount
        require(address(this).balance >= amount);

        // observe before state
        uint beforePot = c.pot(); if (__ESBMC_reverted()) return;
        uint beforeC = address(c).balance;
        uint beforeThis = address(this).balance;

        bool reverted;
        // make the call that may revert
        c.play{value: amount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe after state
        uint afterPot = c.pot(); if (__ESBMC_reverted()) return;
        uint afterC = address(c).balance;
        uint afterThis = address(this).balance;

        // constants from contract C
        uint TICKET = 10;

        // General rule:
        // - If amount != TICKET then the call must revert and nothing observable changes.
        // - If amount == TICKET then the call must not increase the contract's balance by more than TICKET,
        //   and the pot after the call is either beforePot + TICKET or 0.
        assert(
            (amount != TICKET && reverted && afterPot == beforePot && afterC == beforeC && afterThis == beforeThis)
            ||
            (amount == TICKET && !reverted && (afterC - beforeC) <= TICKET && (afterPot == beforePot + TICKET || afterPot == 0))
        );
    }

    // accept Ether if C pays out to this contract during the test
    receive() external payable {}
}

